{
  "hypotheses": [
    {
      "claim": "The `handleAbortError` function throws `signal.reason` for user aborts, but `signal` is undefined when only a timeout occurs (no user-provided signal). This causes a `TypeError` (Cannot read properties of undefined) instead of rejecting with the `TimeoutError` as specified by the contract.",
      "path": "index.js",
      "start_line": 57,
      "end_line": 69,
      "evidence": "const handleAbortError = (timeoutSignal, timeout, signal) => {
	if (timeoutSignal?.aborted) {
		// It's a timeout
		if (typeof timeout === 'object') {
			return handleFallback(timeout);
		}

		throw new TimeoutError();
	}

	// It's a user abort
	throw signal.reason;
};",
      "reproduction": {
        "code": "const {default: pWaitFor, TimeoutError} = await load('./index.js');

// Test 1: Timeout with numeric timeout and no signal should reject with TimeoutError
try {
  await pWaitFor(() => false, { timeout: 10, interval: 5 });
  assert.fail('Should have thrown');
} catch (error) {
  assert.ok(error instanceof TimeoutError, `Expected TimeoutError, got ${error.constructor.name}: ${error.message}`);
}

// Test 2: Timeout with object timeout and no signal should reject with TimeoutError (or fallback)
try {
  await pWaitFor(() => false, { timeout: { milliseconds: 10 }, interval: 5 });
  assert.fail('Should have thrown');
} catch (error) {
  assert.ok(error instanceof TimeoutError, `Expected TimeoutError, got ${error.constructor.name}: ${error.message}`);
}
"
      }
    }
  ]
}
